// Manifest + validation contract (mirrors tests/harness/rag_ingest_core.py)
// Input: items from Read Binary Files (fileName, binary data)
// Output: { manifestHash, entries[], rejected[] }
const crypto = require('crypto');

const items = $input.all();
const files = {};
const rejected = [];

for (const item of items) {
  const bin = item.json.binary;
  if (!bin) { rejected.push('missing binary'); continue; }
  const key = Object.keys(bin)[0];
  const meta = bin[key];
  const fileName = (meta.fileName || '').replace(/\\/g, '/');
  const raw = Buffer.from(meta.data, 'base64');

  // Validation: .md only, NN_ prefix, non-empty, no traversal/absolute path
  if (!fileName.match(/^\d{2}_.+\.md$/)) { rejected.push(fileName + ': unexpected name'); continue; }
  if (fileName.includes('..') || fileName.startsWith('/') || /^[A-Za-z]:[\/]/.test(fileName)) { rejected.push(fileName + ': path rejected'); continue; }
  if (!raw.length) { rejected.push(fileName + ': empty'); continue; }
  try { raw.toString('utf8'); } catch (e) { rejected.push(fileName + ': undecodable'); continue; }

  files[fileName] = raw.toString('utf8');
}

if (rejected.length) {
  return { json: { status: 'failed', rejected: rejected.slice(0, 10), reason: 'validation' } };
}

const sorted = Object.keys(files).sort();
const entries = sorted.map(p => ({ path: p, hash: crypto.createHash('sha256').update(files[p]).digest('hex') }));
const manifestHash = crypto.createHash('sha256')
  .update(entries.map(e => e.path + '\t' + e.hash).join('\n'))
  .digest('hex');

return { json: { status: 'ok', manifestHash, entries, files } };

// Chunking + full-embedding contract (mirrors rag_ingest_core.chunk_document)
// Splits per heading, enforces chunk_size, attaches overlap tail.
// Values must match config_revision frozen values.
const CHUNK_SIZE = 800;
const OVERLAP = 80;

const manifest = $input.first().json;
if (manifest.status !== 'ok') throw new Error('manifest invalid');

function chunkDocument(content) {
  const lines = content.split('\n');
  const base = [];
  let current = [];
  let currentLen = 0;
  for (const line of lines) {
    if (line.trimStart().startsWith('#') && current.length) {
      base.push(current.join('\n'));
      current = []; currentLen = 0;
    }
    current.push(line);
    currentLen += line.length + 1;
    while (currentLen > CHUNK_SIZE && current.length > 1) {
      currentLen -= (current.shift().length + 1);
    }
  }
  if (current.length) base.push(current.join('\n'));
  if (base.length <= 1) return base.filter(c => c.trim());
  const out = [base[0]];
  for (let i = 1; i < base.length; i++) {
    const prefix = base[i-1].slice(-OVERLAP);
    out.push((prefix + '\n' + base[i]).trim());
  }
  return out.filter(c => c.trim());
}

const chunks = [];
for (const entry of manifest.entries) {
  const parts = chunkDocument(manifest.files[entry.path]);
  parts.forEach((text, i) => {
    chunks.push({
      json: {
        source_name: entry.path,
        source_hash: entry.hash,
        chunk_index: i,
        corpus_version: manifest.manifestHash,
        content: text
      }
    });
  });
}
return chunks;

// Pair chunks with embeddings; validate dimension + metadata; prepare staging rows.
const embedData = $input.first().json;
const chunks = $('Chunk Documents').all();
const items = embedData.data || [];
if (!items.length) throw new Error('embedding response missing data');
if (items.length !== chunks.length) throw new Error('chunk/embedding count mismatch');

const EXPECTED_DIM = Number($env.RAG_EMBEDDING_DIMENSION || 0);
const rows = [];
for (let i = 0; i < chunks.length; i++) {
  const vec = items[i].embedding;
  if (!vec) throw new Error('embedding missing');
  if (EXPECTED_DIM && vec.length !== EXPECTED_DIM) throw new Error('dimension mismatch');
  rows.push({
    json: {
      corpus_version: chunks[i].json.corpus_version,
      source_name: chunks[i].json.source_name,
      source_hash: chunks[i].json.source_hash,
      chunk_index: chunks[i].json.chunk_index,
      content: chunks[i].json.content,
      embedding: JSON.stringify(vec),
      embedding_profile_id: $env.EMBEDDING_PROFILE_ID || '',
      query: "INSERT INTO rag.documents (corpus_version, source_name, source_hash, chunk_index, content, embedding, metadata) VALUES ($1, $2, $3, $4, $5, $6::vector, $7::jsonb) ON CONFLICT DO NOTHING"
    }
  });
}
return rows;

// Validate staged candidate before activation
// 1) counts: document_count == entries count, chunk_count == inserted count
// 2) metadata completeness per chunk
// 3) embedding dimension matches config
// 4) single embedding profile

const manifest = $('Build Manifest & Validate').first().json;
const expectedDocs = manifest.entries.length;

// Use DB records (from staging insert result) as source of truth
const inserted = $('Staging: Insert Chunks').all();
const docSet = new Set(inserted.map(i => i.json.corpus_version + i.json.source_name));

if (docSet.size !== expectedDocs) throw new Error('document count mismatch');
return { json: { ok: true, expectedDocs, insertedChunks: inserted.length } };

// On error: mark candidate failed, never touch active pointer
// (handled by n8n error workflow; failure branch keeps old active version)
return { json: { status: 'failed', error_category: $execution.error ? $execution.error.name : 'unknown' } };
